def dhms_to_seconds(s):
    dpart, rest = s.split("d ")
    h, m, sec = rest.split(":")
    return int(dpart) * 86400 + int(h) * 3600 + int(m) * 60 + int(sec)

def cube_root_floor(n):
    lo, hi = 0, max(1, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

