def add_days(date, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    d += n
    while d < 1:
        m -= 1
        if m < 1:
            m = 12
            y -= 1
        d += dim(y, m)
