def tokenize_mixed_alnum(s):
    tokens = []
    current = ""
    current_type = None
    for c in s:
        if c.isalpha():
            ctype = 'alpha'
        elif c.isdigit():
            ctype = 'digit'
        else:
            ctype = None
        if ctype is None:
            if current:
                tokens.append(current)
                current = ""
                current_type = None
            continue
        if ctype == current_type:
            current += c
        else:
            if current:
                tokens.append(current)
            current = c
            current_type = ctype
    if current:
        tokens.append(current)
    return tokens

def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    prefix = ' ' * indent
    return '\n'.join(prefix + line for line in lines)

def sum_of_divisors_squared(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i * i
            j = n // i
            if j != i:
                total += j * j
        i += 1
    return total

