import math
def fraction_from_continued(terms):
    num, den = terms[-1], 1
    for a in reversed(terms[:-1]):
        num, den = a * num + den, num
    if den < 0:
        num, den = -num, -den
    g = math.gcd(num, den)
    return (num // g, den // g)

def group_consecutive_same_case(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return []
    groups = []
    current = letters[0]
    for c in letters[1:]:
        if c.isupper() == current[-1].isupper():
            current += c
        else:
            groups.append(current)
            current = c
    groups.append(current)
    return groups

def total_minutes_worked(sessions):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    total = 0
    for start, end in sessions:
        total += to_min(end) - to_min(start)
    return total

